D.themes=[
{id:"th1",t:"Магия образа",q:"Что делает рисунок «настоящим»?",items:[["icehunters","Пронзённые копьями звери подчиняются охотнику."],["polynesia","Столб с глазами становится живым."],["aboriginal","Тотемный знак рисуется и сегодня."]],more:"Образ не изображает, а действует. Это ключ ко всей главе."},
{id:"th2",t:"Мастерство и «примитивность»",q:"Почему «примитивное» не значит «неумелое»?",items:[["maori","Резьба по дереву, сложная и точная."],["ife","Бронзовые головы с правдоподобными лицами."],["peru","Портретные сосуды из глины."]],more:"Различие не в навыке, а в задаче, которую ставит перед собой художник."},
{id:"th3",t:"Лицо из заданных форм",q:"Как строится лицо, если оно не копирует натуру?",items:[["papua","Маска из однотипных геометрических элементов."],["oro","Две точки-глаза делают чурбан живым."],["tlaloc","Рот и нос из змеиных голов."]],more:"Любые знаки на месте глаз работают, если сохранить их порядок."},
{id:"th4",t:"Образ как письмо",q:"Когда картинка становится знаком?",items:[["haida","Столбы читаются как легенда."],["aztec","Змея как молния и иероглиф."],["maya","Рельеф с религиозным смыслом."]],more:"Изобразительные формы и письменность родственны."}
];
