D.quiz=[
{q:"Как Гомбрих предлагает подходить к искусству прошлого?",o:["Оценивать красоту по современным меркам","Понять цели, которым оно служило","Сравнить мастерство со своим","Искать только шедевры"],a:1,e:"Мы не поймём искусство прошлого, если не знаем, зачем оно создавалось."},
{q:"Какой пример Гомбрих приводит, чтобы показать «примитивное» мышление в нас самих?",o:["Рисунок рожицы","Проткнуть глаза на газетной фотографии любимого чемпиона","Рождественская ёлка","Обручальное кольцо"],a:1,e:"Разумом понимаем, что вреда не будет, но что-то внутри сопротивляется."},
{q:"Какое объяснение пещерных росписей Гомбрих считает наиболее правдоподобным?",o:["Украшение жилища","Магия охоты: образ зверя подчиняет зверя","Обучение детей","Календарь"],a:1,e:"Охотники верили, что, пронзив изображение, они подчинят реального зверя."},
{q:"Что необычного в росписях пещеры Ласко по сравнению с другими?",o:["Они цветные","Они отчётливо различимы на стенах и сводах","Это только лошади","Они на потолке"],a:1,e:"Обычно изображения перекрывают друг друга без видимого порядка."},
{q:"Что такое тотем?",o:["Праздничный наряд","Животное-сородич и покровитель племени","Вид маски","Древний календарь"],a:1,e:"Племена считают себя потомками волка, ворона, лягушки и так далее."},
{q:"Что главное для племенного художника?",o:["Новизна и оригинальность","Способность вещи «срабатывать» в обряде","Подпись мастера","Соответствие натуре"],a:1,e:"Критерий — не красота, а способность исполнять роль в магическом обряде."},
{q:"С чем Гомбрих сравнивает украшение рождественской ёлки?",o:["С охотой","С творчеством в рамках установленных правил","С рисованием с натуры","С архитектурой"],a:1,e:"Обычай задан, но внутри правил остаётся простор для вкуса и мастерства."},
{q:"Что доказывают бронзовые головы из Нигерии?",o:["Что африканские мастера заимствовали технику","Что мастер племенного общества мог передать натуру точно","Что магия не работает","Что бронза была редкостью"],a:1,e:"Головы были сделаны несколько столетий назад, оснований для заимствования нет."},
{q:"Как Гомбрих формулирует мысль об истории искусства?",o:["Это путь от неумелого к умелому","Это не накопление технических навыков, а смена идей и критериев","Это история великих имён","Это история стилей"],a:1,e:"Различие между культурами в идейных установках, а не в мастерстве."},
{q:"Что показывает опыт с рожицей без глаз?",o:["Что художник должен рисовать с натуры","Что глаза делают фигуру «живой», а их форма может быть любой","Что лица всегда симметричны","Что маски лучше портретов"],a:1,e:"Любые значки на месте глаз работают, если их положение сохранено."},
{q:"Что рассказывает центральный столб на макете дома хайда?",o:["Историю о юноше, убившем чудовище","Историю основания деревни","Родословную вождя","Календарь"],a:0,e:"Все персонажи легенды расположены сверху вниз: киты, чудовище, тёща, птица, юноша, дети."},
{q:"Чем была змея в искусстве Древней Мексики?",o:["Только украшением","Животным, молнией и знаком письма одновременно","Только знаком смерти","Цветом"],a:1,e:"Из этого Гомбрих делает вывод: изобразительные формы и письмена кровные родственники."},
{q:"Что Гомбрих говорит о майя, ацтеках и инках?",o:["Они были примитивными","Они не были примитивными в обычном смысле: города, письменность, календарь","Они не умели рисовать лицо","Они ничего не оставили"],a:1,e:"Но их задачи были другими, поэтому искусство кажется нам странным."}
];
